using System;
using Game.Combat;
using Game.Utils;
using UnityEngine;

namespace Game.Enemies
{
    /// <summary>Vida de un enemigo.</summary>
    public class EnemyHealth : MonoBehaviour, IDamageable
    {
        private int _currentHealth;
        private bool _isDead;

        /// <summary>Se dispara una sola vez, cuando la vida llega a 0.</summary>
        public event Action OnDied;

        /// <summary>Vida actual.</summary>
        public int CurrentHealth => _currentHealth;

        /// <summary>Indica si el enemigo ha muerto.</summary>
        public bool IsDead => _isDead;

        private void Awake()
        {
            _currentHealth = GameBalance.EnemyBaseHealth;
        }

        /// <summary>Resta vida sin bajar de cero. Dispara OnDied al morir.</summary>
        public void TakeDamage(int amount)
        {
            if (_isDead || amount <= 0) return;
            _currentHealth = Mathf.Max(_currentHealth - amount, 0);
            if (_currentHealth > 0) return;
            _isDead = true;
            OnDied?.Invoke();
        }
    }
}

