using System;
using Game.Combat;
using UnityEngine;

namespace Game.Player
{
    /// <summary>Vida del jugador.</summary>
    public class PlayerHealth : MonoBehaviour, IDamageable
    {
        [SerializeField] private int _maxHealth = 100;
        private int _currentHealth;

        /// <summary>Se dispara con (vida actual, vida máxima) cuando la vida cambia.</summary>
        public event Action<int, int> OnHealthChanged;

        /// <summary>Vida actual.</summary>
        public int CurrentHealth => _currentHealth;

        /// <summary>Vida máxima.</summary>
        public int MaxHealth => _maxHealth;

        private void Awake()
        {
            _currentHealth = _maxHealth;
        }

        /// <summary>Resta vida sin bajar de cero.</summary>
        public void TakeDamage(int amount)
        {
            if (amount <= 0) return;
            int previous = _currentHealth;
            _currentHealth = Mathf.Max(_currentHealth - amount, 0);
            if (_currentHealth != previous)
                OnHealthChanged?.Invoke(_currentHealth, _maxHealth);
        }

        /// <summary>Suma vida sin superar el máximo.</summary>
        public void Heal(int amount)
        {
            if (amount <= 0) return;
            int previous = _currentHealth;
            _currentHealth = Mathf.Min(_currentHealth + amount, _maxHealth);
            if (_currentHealth != previous)
                OnHealthChanged?.Invoke(_currentHealth, _maxHealth);
        }
    }
}
